// Expand to reach ~485 total books with variants, classic foundational companion volumes, and translations
const ALL_BOOKS = [];

for (const [category, books] of Object.entries(RAW_BOOKS_BY_CATEGORY)) {
  for (const b of books) {
    ALL_BOOKS.push({
      title: b.title,
      authors: b.authors,
      category,
      collection: b.col,
      tags: b.tags,
      publisher: b.pub,
      rating: b.rating,
      pubdate: `${b.year > 0 ? b.year : 1900}-01-01 00:00:00+00:00`,
      language: "eng",
      formats: Math.random() > 0.3 ? ["EPUB", "PDF"] : ["EPUB", "PDF", "MOBI"],
      description: `A seminal work in ${category} by ${b.authors.join(", ")}. Exploring core themes including ${b.tags.join(", ")}.`
    });
  }
}

console.log(`Curated database contains ${ALL_BOOKS.length} books.`);

const fileContent = `// Auto-generated curated real books dataset across 10 disciplines
export const REAL_BOOKS = ${JSON.stringify(ALL_BOOKS, null, 2)};
`;

fs.writeFileSync(path.resolve(process.cwd(), 'scripts/demo-books-dataset.mjs'), fileContent);
console.log('Saved scripts/demo-books-dataset.mjs');
